let availability_verbiage = $('Check Calendar Availability').first().json.available ? "available" : "unavailable";
let message = `<strong>Availability</strong>\nAccording to your agenda, you are ${ availability_verbiage }. Events that day:\n`;

let events_that_day = $('Retrieve Daily Events').all();
if (events_that_day.length == 0) {
  message += "None."
}

for (let event of events_that_day) {
  let start_datetime = DateTime.fromJSDate(new Date(event.json.start.dateTime));
  let start_datetime_formatted = `${ start_datetime.toFormat("HH:mm") }`;
  message += `• ${ event.json.summary } (at ${ start_datetime_formatted })\n`;
}

return [{ "availability_message": message }];
